#include <map>
#include <string>
#include <algorithm>
#include <iostream>

int main() {
    std::map<int, std::string> users = {{1, "Alice"}, {2, "Bob"}};
    const std::string target_value = "Bob";

    // O(N) search using find_if (searching by value)
    auto pos = std::find_if(users.begin(), users.end(), 
        [&](const auto& pair) { 
            return pair.second == target_value; 
        }
    );

    if (pos != users.end()) {
        std::cout << "Found user '" << pos->second 
                  << "' with Key: " << pos->first << " (O(N))\n";
    }
    return 0;
}
